<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Password Entropy Calculator','description'=>'Estimate password entropy from length and character classes locally.','url'=>'https://smarttoolz.in/tools/password-entropy/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>Password Entropy Calculator</h1><p>Estimate entropy in bits from password length and character variety.</p><input id="p" type="password" placeholder="Enter password"><button id="go">Calculate Entropy</button><div id="o"></div></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool input{width:100%;box-sizing:border-box;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{margin-top:12px;padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool #o{margin-top:16px;padding:16px;background:#f6f7fb;border-radius:12px}</style><script>go.onclick=()=>{let x=p.value,n=0;if(/[a-z]/.test(x))n+=26;if(/[A-Z]/.test(x))n+=26;if(/\d/.test(x))n+=10;if(/[^A-Za-z0-9]/.test(x))n+=32;o.textContent=x&&n?'Estimated entropy: '+(x.length*Math.log2(n)).toFixed(1)+' bits':'Enter a password.'}</script><?php smarttoolz_tool_page_end(); ?>